sys_ws_schema.schema:
{
  "type": "object",
  "properties": {
    "short_description": {
      "type": "string",
      "description": "Short description for the story"
    },
    "description": {
      "type": "string",
      "description": "Detailed description of the story"
    },
    "acceptance_criteria": {
      "type": "string",
      "description": "Acceptance criteria for the story"
    },
    "project": {
      "type": "string",
      "description": "Project number or the sys_id of the project"
    },
    "sprint": {
      "type": "string",
      "description": "Sprint name, number, or sys_id"
    },
    "story_points": {
      "type": "number",
      "description": "Story point estimate"
    },
    "assigned_to": {
      "type": "string",
      "description": "user_name, email, or sys_id of the user to assign to"
    },
    "assignment_group": {
      "type": "string",
      "description": "group name or the sys_id of the assignment group"
    },
    "priority": {
      "type": "string",
      "description": "Priority value for the story"
    }
  },
  "required": [
    "short_description"
  ]
}
